// kaya runtime for Go guests: cgo, loading, the direct-ring occurrence
// loop, and submit. Hand-written; the wire vocabulary next to it
// (kaya_wire.go) is generated by kaya-bindgen.
//
// The direct tier: Go reads the occurrence ring with its own atomics —
// cgo is crossed only to start the core, to wait on an empty ring, and
// to submit. The consumer contract is the io_uring recipe documented in
// kaya.h. Call Init once, run the occurrence loop on one goroutine, and
// give kaya the process main thread via Run (runtime.LockOSThread in
// the caller's init).
//
// THE #cgo LINES ARE PER-PLATFORM AND THE NEGATIONS ARE LOAD-BEARING.
// GOOS=ios also satisfies the `darwin` build tag, so an unqualified
// `#cgo darwin` line answers for iOS too and points the link at the
// macOS build — the failure is `ld: building for 'iOS-simulator', but
// linking in dylib built for 'macOS'`, at the end of a cross-build that
// looked fine until then. `darwin,!ios` is what keeps the two apart.
// GOOS=android satisfies `linux` exactly the same way, and its own line
// points at the NDK-built target dir the android lane fills
// (target/aarch64-linux-android/debug/libkaya.so, the same .so the APK
// carries in jniLibs) — so `linux,!android` is the second half of the
// same rule.
//
// Android names -lkaya rather than a path because the artifact is a
// SHARED library there and the app's linker resolves it at load time:
// the APK ships libkaya.so beside the guest's own .so, and both are
// found by SONAME under the app's linker namespace. That is the
// opposite of the iOS line below for the opposite reason — iOS has one
// executable and nowhere to put a dylib, Android has a jniLibs
// directory and a linker namespace that already holds one.
//
// The ios line NAMES THE ARCHIVE BY PATH rather than using -L/-lkaya,
// and that is not a style choice: target/aarch64-apple-ios-sim/debug
// holds both libkaya.a and libkaya.dylib, and ld64 prefers the dylib
// when both answer -lkaya. A bundle linked that way carries an absolute
// build-machine path to a library outside itself and runs only in the
// Simulator, where the host filesystem happens to be visible — which is
// exactly the defect the Swift leg still has (mobilepkg-contract.md
// §1.2). Naming the .a is what makes the bundle self-contained, and
// `otool -L` is what proves it.
//
// The path is the SIMULATOR triple because that is the only iOS the
// lane runs (tools/ios/run-sim.sh; bundles are unsigned, no device is
// attached). A device build wants
// target/aarch64-apple-ios/debug/libkaya.a instead; it fails loudly at
// link time rather than silently, ld naming both platforms.
package kaya

/*
#cgo CFLAGS: -I${SRCDIR}/../../crates/kaya/include -I${SRCDIR}/../.. -I${SRCDIR}
#cgo darwin,!ios LDFLAGS: -L${SRCDIR}/../../target/debug -lkaya -Wl,-rpath,${SRCDIR}/../../target/debug
#cgo ios LDFLAGS: ${SRCDIR}/../../target/aarch64-apple-ios-sim/debug/libkaya.a -framework UIKit -framework Foundation -framework CoreFoundation -framework CoreGraphics -framework QuartzCore
#cgo windows LDFLAGS: -L${SRCDIR}/../.. -L${SRCDIR}/../../target/aarch64-pc-windows-msvc/release -lkaya
#cgo linux,!android LDFLAGS: -L${SRCDIR}/../../target-linux/debug -lkaya -Wl,-rpath,${SRCDIR}/../../target-linux/debug
#cgo android LDFLAGS: -L${SRCDIR}/../../target/aarch64-linux-android/debug -lkaya
#include <kaya.h>
*/
import "C"

import (
	"bytes"
	"fmt"
	"os"
	"runtime"
	"sync/atomic"
	"unsafe"
)

// hostedEntry is true where the OPERATING SYSTEM owns the process entry
// and hands kaya a thread, rather than the guest owning main and lending
// it. Android and nothing else: Zygote forks the process, ActivityThread
// owns the Looper, and kaya_run is a hard panic there
// (crates/kaya/src/capi.rs:815-818).
//
// A CONSTANT, NOT A VARIABLE, and that is what makes the two arms it
// selects free: runtime.GOOS is itself a constant, so the compiler keeps
// one arm and drops the other, while the type checker sees both on every
// platform. Every place this appears would otherwise be a build-tagged
// file pair that only one lane ever compiles — the hole
// bindings/go/android.go's header refuses to open.
const hostedEntry = runtime.GOOS == "android"

// THE APP THREAD IS CLAIMED BY THE BINDING, NOT BY THE GUEST, so that a
// guest's main.go carries no platform knowledge and no build tags.
//
// The core must own the process main thread on every host where there is
// one — a UI framework's event loop is not portable off thread 0 on
// macOS or Windows — and Go will migrate a goroutine between Ms unless
// it is told not to. Package initialization runs on the main goroutine
// in dependency order, so this init runs BEFORE any of the guest's, and
// before main: the earliest moment the lock can be taken.
//
// NOT ON ANDROID, and the exception is not symmetry-breaking so much as
// the same rule applied to a host with no process entry to claim. Go's
// package inits there run while System.loadLibrary is still executing,
// on a thread the Go runtime made for itself, and the goroutine running
// them is the library's main goroutine — which exits as soon as
// initialization finishes (runtime.main returns early under
// `isarchive || islibrary` instead of calling main.main). A goroutine
// that exits while holding an OS thread takes the thread with it. The
// app thread there is made and locked by the attach entry instead
// (bindings/go/android.go), which is the thread that will actually park
// inside the core.
func init() {
	if !hostedEntry {
		runtime.LockOSThread()
	}
}

var ring C.KayaRingInfo

// Init fetches the ring layout. Call once, before the occurrence loop.
func Init() {
	C.kaya_occurrence_ring(&ring)
}

// Env reads one environment variable AS THE HOST PROCESS SEES IT, and
// is the only spelling a kaya guest may use. Empty when unset; use
// LookupEnv to tell an unset variable from one set to the empty string.
//
// os.Getenv IS NOT AN ALTERNATIVE SPELLING OF THIS, AND ON ANDROID IT
// IS SILENTLY WRONG. Go fills runtime.envs from the envp handed to the
// PROCESS ENTRY. An -buildmode=c-shared library loaded by
// System.loadLibrary never sees one, so Go's view of the environment is
// empty forever while C's getenv(3) reads the live `environ` the host
// wrote — measured side by side in a real app process
// (mobilepkg-go.md §4.4): os.Getenv("KAYA_SELFTEST") == "" and
// len(os.Environ()) == 0 while C.getenv("KAYA_SELFTEST") == "milestone2".
//
// The consequence is the reason this function exists rather than a
// comment somewhere. kaya picks its scene by name from KAYA_SELFTEST,
// and the selector's guard is a panic on an UNKNOWN name — but "" is
// not an unknown name, it is the default arm, so the idiomatic Go
// spelling runs milestone2 against every other scene's script and fails
// every step for the wrong reason. It works on iOS, where the guest is
// -buildmode=exe and Go owns main, so the natural build order tests the
// broken call on the platform where it is not broken.
//
// tools/check-go-env.sh keeps os.Getenv/os.LookupEnv/os.Environ out of
// bindings/go and guests/go, because nothing at compile time or run
// time can tell the two spellings apart: both compile everywhere, and
// on Android both return a value — one right, one empty.
func Env(name string) string {
	value, _ := LookupEnv(name)
	return value
}

// LookupEnv is Env with the found bit, for a caller that must tell
// unset from set-to-empty. Same C view, same reason.
func LookupEnv(name string) (string, bool) {
	key := C.CString(name)
	defer C.free(unsafe.Pointer(key))
	// getenv returns a pointer INTO the host's environ, live and
	// borrowed; GoString copies before anything can rewrite it.
	value := C.getenv(key)
	if value == nil {
		return "", false
	}
	return C.GoString(value), true
}

// The stale-artifact guard, run once before the core takes the thread:
// this binding was generated from one spec revision; the loaded library
// must speak the same one.
func checkSpec() {
	if got := uint64(C.kaya_spec_hash()); got != SpecHash {
		panic(fmt.Sprintf(
			"kaya: library speaks spec %#016x, this binding was generated from %#016x — rebuild the library or regenerate bindings",
			got, SpecHash))
	}
}

// Run enters the core on the calling thread and returns the exit code
// when the app ends. THE THREAD MUST BE THE PROCESS MAIN THREAD, which
// the binding's init above arranges on every host that has one.
//
// A GUEST CALLS App.Run, NOT THIS. This is the desktop half of App.Run's
// body and it is exported only because the occurrence loop and the core
// loop are separable — App.Run runs one on each. Calling it directly on
// Android panics inside the core, naming the reason ("Android owns the
// process entry; attach from an Activity instead of kaya_run"), which is
// the right answer to a call that should not have been written.
func Run() int {
	checkSpec()
	return int(C.kaya_run())
}

// Submit sends one transaction: the concatenation of packed records
// (Tx* results), applied atomically.
func Submit(records ...[]byte) {
	var tx []byte
	for _, r := range records {
		tx = append(tx, r...)
	}
	C.kaya_submit((*C.uint8_t)(unsafe.Pointer(&tx[0])), C.size_t(len(tx)))
}

// RegisterBlob registers bulk payload bytes (an encoded image) with
// the core: one copy into core-owned memory, returning the u64 handle
// the next submit from this guest consumes (referenced or not). The
// caller's bytes are free to drop the moment this returns.
func RegisterBlob(data []byte) uint64 {
	if len(data) == 0 {
		// &data[0] does not exist for an empty slice; a one-byte
		// stand-in with length 0 keeps the C side off a null pointer.
		var zero C.uint8_t
		return uint64(C.kaya_blob_register(&zero, 0))
	}
	return uint64(C.kaya_blob_register((*C.uint8_t)(unsafe.Pointer(&data[0])), C.size_t(len(data))))
}

// occurrenceBlob redeems an occurrence blob for its bytes, and
// releases it. Called by the generated decoder, never by a guest.
//
// COPY THEN RELEASE, in that order: the pointer borrows core memory
// that the release frees. A blob arriving in an OCCURRENCE is a handle
// into a table with no boundary that retires one — unlike the apply
// channel's batch-local index, which the next batch supersedes — so
// the decoder is what has to let go of it, while decoding, before any
// handle can reach an app. Release is idempotent, so a dead handle
// costs nothing rather than being an error the decoder must reason
// about.
func occurrenceBlob(handle uint64) []byte {
	var length C.size_t
	data := C.kaya_occurrence_blob(C.uint64_t(handle), &length)
	var out []byte
	if data != nil && length > 0 {
		out = C.GoBytes(unsafe.Pointer(data), C.int(length))
	}
	C.kaya_occurrence_blob_release(C.uint64_t(handle))
	return out
}

// PollOccurrence reads the next occurrence if one is ready and NEVER
// blocks; ready is false when the ring is empty right now. keys is nil
// when id is a widget id, else id is a template node id and keys is the
// stamped copy's key path, outermost first. payload carries the entry's
// new text (string) for OccurrenceTextChanged, the checkbox's new state
// (bool) for OccurrenceToggled.
//
// Polling and waiting are separate calls, rather than one blocking
// NextOccurrence, because the app goroutine has a SECOND source of work:
// closures posted from other goroutines. A single blocking read would
// park inside C with no way back out to drain them — the loop in App.Run
// is what needs both halves.
func PollOccurrence() (kind uint16, id uint64, keys []any, payload any, ready bool) {
	head := (*uint32)(unsafe.Pointer(ring.head))
	tail := (*uint32)(unsafe.Pointer(ring.tail))
	data := uintptr(unsafe.Pointer(ring.data))
	mask := uint32(ring.capacity) - 1

	h := atomic.LoadUint32(head)
	for {
		t := atomic.LoadUint32(tail) // acquire: records below are visible
		if h == t {
			return 0, 0, nil, nil, false
		}
		at := data + uintptr(h&mask)
		size := *(*uint32)(unsafe.Pointer(at))
		rec := unsafe.Slice((*byte)(unsafe.Pointer(at)), size)
		kind, id, keys, payload, valid := ParseOccurrence(rec)
		h += size
		atomic.StoreUint32(head, h) // release: hand the space back
		if valid {
			return kind, id, keys, payload, true
		}
		// A pad or an unparsable record: consume it and keep looking,
		// still without blocking.
	}
}

// WaitOccurrences blocks until there MAY be something to do: a record
// arrived, or another goroutine called Wake. Returns false once the core
// has shut down and the ring is drained.
//
// "May" is the honest word. A wake returns true with the ring still
// empty, and the caller is expected to re-check both sources rather than
// trust the return — which is exactly what a drain-then-poll loop does
// anyway.
func WaitOccurrences() bool {
	return bool(C.kaya_wait_occurrences())
}

// Wake returns the app goroutine from WaitOccurrences. Safe from any
// goroutine; the binding calls it from Post, and guests do not name it.
func Wake() {
	C.kaya_wake()
}

// Asset is one open asset: the bytes of a file the app's own BUILD
// shipped, held by the core and named the same way on five platforms
// (docs/assets-plan.md, ratified 2026-08-18). Tx.Asset opens one.
//
//	font := tx.Asset("fonts/sora-wght.ttf")
//	defer font.Close()
//	tx.BrandTypeface("Sora", kaya.FontAsset(font))
//
// WHERE that name resolves is the core's knowledge and never the app's:
// a directory in a repo checkout, a .app bundle's Resources, an APK's
// packaged assets/, which is not a directory and has no path at all.
// Before this existed the rule was hand-written once per guest language,
// and GO'S COPY IS THE ONE THAT HAD A GATE WRITTEN FOR IT — a guest
// resolving a font through an environment variable had to remember
// kaya.Env, because os.Getenv in a c-shared library reads an environment
// that is empty forever (tools/check-go-env.sh). Moving the read into
// the core does not gate that trap, it makes it unreachable: no guest
// reads an environment variable at all.
//
// TWO REDEMPTIONS, and the first is the interesting one:
//
//   - HAND IT TO KAYA. kaya.FontAsset(a) and tx.AppIdentityAsset(name,
//     a) take an Asset, and the bytes never enter Go: the core clones a
//     refcount into the blob table the wire already has.
//   - READ IT YOURSELF. Bytes copies them out, and Reader wraps that
//     copy in a *bytes.Reader.
//
// FILE-LIKE READING IS THIS BINDING'S SUGAR, with zero core surface:
// Reader is a bytes.Reader the way Python's is a BytesIO and C#'s a
// MemoryStream. THERE IS NO FILE DESCRIPTOR anywhere on the asset
// surface — a descriptor was PickedFile's necessity below, because a
// provider-opened file has no path behind it, and kaya resolved this
// name and produced these bytes itself. Read-only structurally, too: no
// call here takes a mode.
//
// AN fs.FS FAÇADE IS ADMITTED, NOT REFUSED, and it is deliberately not
// written yet (the plan's ruling): it is legal binding-side sugar the
// same tier as bytes.NewReader, and the trigger is a real Go artifact
// that wants to hand its assets to something FS-shaped
// (http.FileServer, template.ParseFS). Until one does, Bytes plus
// bytes.NewReader is the whole Go surface.
//
// CLOSING. Close releases the core's handle, and a cleanup releases one
// a guest forgot — so a guest that never closes leaks nothing, and one
// that closes twice pays nothing (the core's release is idempotent).
type Asset struct {
	handle uint64
	name   string
}

// openAsset is Tx.Asset's floor: the handle, or 0 for a miss. The
// sentence for a miss is assetMissSentence's, and the raise is app.go's.
func openAsset(name string) *Asset {
	raw := []byte(name)
	var handle C.uint64_t
	if len(raw) == 0 {
		// &raw[0] does not exist for an empty slice, and an empty name
		// is a real call the core has a sentence for ("names nothing"),
		// so it must reach the core rather than being refused here.
		var zero C.uint8_t
		handle = C.kaya_asset_open(&zero, 0)
	} else {
		handle = C.kaya_asset_open((*C.uint8_t)(unsafe.Pointer(&raw[0])), C.size_t(len(raw)))
	}
	if handle == 0 {
		return nil
	}
	asset := &Asset{handle: uint64(handle), name: name}
	// THE FORGETTING GUEST'S NET. The cleanup captures the HANDLE by
	// value and never the Asset — a cleanup that closed over the object
	// would keep it reachable forever and never run, which is the
	// classic way this net is written wrong. Release is idempotent, so
	// a cleanup that fires after an explicit Close costs nothing and
	// needs no bookkeeping to suppress.
	runtime.AddCleanup(asset, func(handle uint64) {
		C.kaya_asset_release(C.uint64_t(handle))
	}, asset.handle)
	return asset
}

// assetMissSentence CARRIES the core's sentence for why an open would
// fail — empty
// when it would succeed.
//
// ASKED TWICE ON PURPOSE. The first call passes a nil buffer to learn
// the length; the second fills a buffer of exactly that size. A fixed
// buffer would truncate the END of the sentence, which is where the
// census of what the package actually carries lives — the half that
// answers the reader's next question.
//
// THE PROSE IS THE CORE'S, whole and unedited: one author for the
// sentence, nine spellings of the raise.
// NAMED FOR THE CARRYING, not for the answering, and deliberately not
// `assetWhyNot`. tools/check-diagnostics.sh reads any *WhyNot by that
// name alone and holds it to the rule that every branch must print
// what it measured — which is right, and which the function that
// EARNED the name already satisfies: `asset_why_not` in
// crates/kaya/src/assets.rs stats the root, lists what is there and
// reads the io error, and the gate audits it at answers=8,
// measured=8. This copies that sentence's bytes into a Go string. It
// observes nothing and could not print a second sentence if it tried,
// so calling it a why-not would put a diagnostic's name on a
// memcpy — and three other bindings in this same slice named theirs
// the same way (OCaml's asset_miss_sentence).
func assetMissSentence(name string) string {
	raw := []byte(name)
	var (
		namePtr *C.uint8_t
		zero    C.uint8_t
	)
	if len(raw) == 0 {
		namePtr = &zero
	} else {
		namePtr = (*C.uint8_t)(unsafe.Pointer(&raw[0]))
	}
	needed := int(C.kaya_asset_why_not(namePtr, C.size_t(len(raw)), nil, 0))
	if needed == 0 {
		return ""
	}
	out := make([]byte, needed)
	written := int(C.kaya_asset_why_not(namePtr, C.size_t(len(raw)),
		(*C.uint8_t)(unsafe.Pointer(&out[0])), C.size_t(needed)))
	return string(out[:min(written, needed)])
}

// Name is the name this asset was asked for — what Tx.Asset was given,
// not a path. There is no path to hand back on Android at all, so none
// of the nine bindings offers one.
func (a *Asset) Name() string { return a.name }

// Bytes copies the asset's bytes out of core memory.
//
// ONE COPY, AND IT IS NOT AVOIDABLE HERE: the C pointer borrows the
// core's allocation, and a Go slice aliasing it would outlive the
// release. The copy is the price of reading in Go; the BLOB redemption
// pays nothing, and it is the route a font or an icon takes.
func (a *Asset) Bytes() []byte {
	a.alive("Bytes")
	var length C.size_t
	data := C.kaya_asset_bytes(C.uint64_t(a.handle), &length)
	var out []byte
	if data != nil && length > 0 {
		out = C.GoBytes(unsafe.Pointer(data), C.int(length))
	}
	// The cleanup above releases the handle the moment this Asset is
	// unreachable, and "unreachable" can happen while a method that no
	// longer touches the receiver is still running: the release would
	// then race the read above and this would answer nil. KeepAlive is
	// what makes the object reachable until the C call has returned.
	runtime.KeepAlive(a)
	return out
}

// Reader is the asset as an io.Reader/io.Seeker: a *bytes.Reader over a
// copy of the bytes. Entirely Go's — the core knows nothing about it.
func (a *Asset) Reader() *bytes.Reader { return bytes.NewReader(a.Bytes()) }

// Len is the asset's byte count. Never 0 for a live asset: the core
// refuses a zero-byte asset at the open, because an empty blob sails
// through every lowering and is indistinguishable from a default.
func (a *Asset) Len() int {
	a.alive("Len")
	n := int(C.kaya_asset_len(C.uint64_t(a.handle)))
	runtime.KeepAlive(a)
	return n
}

// Close releases the core's handle. Idempotent, and safe to defer
// beside the open.
func (a *Asset) Close() {
	handle := a.handle
	a.handle = 0
	if handle != 0 {
		C.kaya_asset_release(C.uint64_t(handle))
	}
	runtime.KeepAlive(a)
}

// blobHandle is THE BLOB REDEMPTION, used by the two consumers that
// take an Asset: it registers the core's own bytes into the pending
// table and answers the handle the next submit consumes. The bytes
// never enter Go.
//
// UNEXPORTED, because the redemption is the binding's business and not
// the guest's: FontAsset and AppIdentityAsset are the whole offer, and
// they are the same offer in all nine languages.
func (a *Asset) blobHandle() uint64 {
	a.alive("a blob redemption")
	handle := uint64(C.kaya_asset_blob(C.uint64_t(a.handle)))
	runtime.KeepAlive(a)
	return handle
}

// alive is the asset's one panic, shared by every method that reads the
// handle so the two cannot drift in what they say — Tx.alive's shape,
// one table over.
func (a *Asset) alive(what string) {
	if a == nil || a.handle == 0 {
		name := ""
		if a != nil {
			name = a.name
		}
		panic(fmt.Sprintf("kaya: %s on a closed asset (%q) — the handle was "+
			"released, and the bytes it borrowed are the core's. Read before "+
			"Close, or keep the bytes rather than the asset.", what, name))
	}
}

// PickedFile is one file the picker answered with: a handle to redeem,
// a display name, and LocalPath — a RE-OPENABLE NAME, empty unless
// re-opening it actually works, which measurement puts at the three
// desktops and neither phone (DESIGN.md, File dialogs).
type PickedFile struct {
	Handle    uint64
	Name      string
	LocalPath string
}

// Open redeems the handle for a real *os.File, plus whether it seeks.
//
// BLOCKS, and may block for a long time — a cloud provider can download
// the file before it answers — so call it from a goroutine you chose
// and post the result back (DESIGN.md, File dialogs).
//
// THE FILE BECOMES GO'S. os.NewFile takes the descriptor over, so
// closing the returned *os.File closes it exactly once and the core
// keeps no claim. On Windows the core hands back a HANDLE rather than a
// CRT descriptor — deliberately, since every runtime brings its own CRT
// — and os.NewFile takes a HANDLE there, so the same line is right on
// both.
//
// Seekable RIDES THE OPEN rather than the pick because that is the only
// place the answer exists: an Android provider may hand back a pipe,
// and nothing short of opening reveals it. Go's io/fs.File is satisfied
// either way; only io.Seeker depends on this.
//
// A SAVE DESTINATION OPENS EMPTY, whichever mode you ask for: a handle
// from Tx.SaveFile creates the file the dialog named, because macOS, GTK
// and Windows answer with a name for a file nobody has made while
// Android and iOS answer with one that exists (docs/save-plan.md D1).
// The create is the DESTINATION's property, never the mode's — a handle
// from Tx.PickFiles never creates anything, so FileModeWrite on a file
// the user merely opened cannot conjure a new one.
func (f PickedFile) Open(mode uint32) (file *os.File, seekable bool, err error) {
	var raw C.int64_t
	var seeks C.uint32_t
	rc := C.kaya_open_picked(C.uint64_t(f.Handle), C.uint32_t(mode), &raw, &seeks)
	if rc != 0 {
		return nil, false, fmt.Errorf("kaya: opening the picked file failed (code %d)", int(rc))
	}
	return os.NewFile(uintptr(raw), f.Name), seeks != 0, nil
}
